import{_ as e}from"./chunks/plugin-vue_export-helper.DlAUqK2U.js";import{c as a,o as r,af as i}from"./chunks/mermaid.DEOxUarQ.js";import"./chunks/cytoscape.C2CwDKBM.js";import"./chunks/dayjs.C32PoDnw.js";const m=JSON.parse(`{"title":"Interpretability (Bridge)","description":"Why the model produced this output — mechanistic interpretability (superposition, features, attribution graphs) bridges entirely to Learn LLM; this repo keeps only the app engineer's positional sense: it shapes trust boundaries, audit promises, and expectations when debugging 'why did it say that'.","frontmatter":{"title":"Interpretability (Bridge)","description":"Why the model produced this output — mechanistic interpretability (superposition, features, attribution graphs) bridges entirely to Learn LLM; this repo keeps only the app engineer's positional sense: it shapes trust boundaries, audit promises, and expectations when debugging 'why did it say that'.","domain":"tech","tags":["tech","interpretability","bridge","safety"],"navOrder":91,"topicId":"interpretability","layer":"9","status":"bridge","nodeType":"boundary","owner":"learn-ai","externalOwners":[{"site":"llm","url":"https://llm.zenheart.site/"}],"lastVerified":"2026-09-01","bilingualParity":"exact","listed":true},"headers":[],"relativePath":"tech/09-advanced/interpretability.md","filePath":"tech/09-advanced/interpretability.md","lastUpdated":1791174142000}`),o={name:"tech/09-advanced/interpretability.md"};function n(s,t,l,d,h,p){return r(),a("div",null,[...t[0]||(t[0]=[i('<blockquote><p><strong>Group</strong>: Advanced (bridge) | <strong>Previous group exit</strong>: run long-term with release gates and versioning | <strong>This page exit</strong>: know which engineering decision this topic affects, and when to go to Learn LLM</p></blockquote><h1 id="interpretability-bridge" tabindex="-1">Interpretability (Bridge) <a class="header-anchor" href="#interpretability-bridge" aria-label="Permalink to &quot;Interpretability (Bridge)&quot;">​</a></h1><blockquote><p><strong>Bridge page</strong>: mechanistic interpretability — superposition, sparse autoencoders, feature decomposition, attribution graphs — with derivations and experiments lives in <a href="https://llm.zenheart.site/" target="_blank" rel="noreferrer">Learn LLM</a> (Chapter 7 · Transformer internals). This repo answers only the app engineer&#39;s question: <strong>which of my decisions it changes, and when what you need is actually something else.</strong></p></blockquote><h2 id="_1-overview" tabindex="-1">1. Overview <a class="header-anchor" href="#_1-overview" aria-label="Permalink to &quot;1. Overview&quot;">​</a></h2><p><strong>What problem it solves</strong>: the model is a black box — you observe inputs and outputs, but &quot;why it said that&quot; hides in the middle layers. Interpretability research opens those layers: decomposing activations into readable &quot;features&quot;, then tracing causal chains between features (attribution graphs), turning &quot;why&quot; into inspectable evidence.</p><p><strong>Why app engineers need positional sense</strong>: you are not going to dissect the model; you are managing three engineering responsibilities created by the black box:</p><ul><li><strong>Trust boundary</strong>: how deep a behavioral guarantee can you make externally? &quot;We cannot explain why it refuses or doesn&#39;t&quot; is a compliance gap in high-stakes settings, not an academic one.</li><li><strong>Debugging expectations</strong>: application-layer tools (evals, traces, ablations) answer only &quot;did behavior change&quot;; &quot;why inside the model&quot; is beyond the application toolbox — knowing this boundary keeps you from wasting time at the wrong layer.</li><li><strong>Narrative calibration</strong>: &quot;planning&quot; or &quot;hidden goals&quot; shown by attribution graphs are products of research tooling; treat them as an evidence framework in communication, not proof that &quot;the model is conscious&quot;.</li></ul><h2 id="_2-usage" tabindex="-1">2. Usage <a class="header-anchor" href="#_2-usage" aria-label="Permalink to &quot;2. Usage&quot;">​</a></h2><p>The decisions it shapes (positions, not code):</p><table tabindex="0"><thead><tr><th>Decision</th><th>The positional sense interpretability gives</th></tr></thead><tbody><tr><td>Model selection for high-stakes flows</td><td>Black-box depth is a selection cost: the less explainable the behavior&#39;s origin, the more external guardrails (eval gates, human review) must compensate</td></tr><tr><td>Audit promises to customers/regulators</td><td>Promise only what the application layer can prove (traces, eval records); &quot;internally explainable&quot; is currently a research frontier, not a deliverable</td></tr><tr><td>Debugging &quot;why this output&quot;</td><td>Application layer first: trace and context reconciliation (→ <a href="./../08-production/observability.html">Observability</a>), input ablation, eval-set comparison; only when all point to &quot;that&#39;s just the model&quot; does this section apply</td></tr><tr><td>Product copy and mental models</td><td>&quot;Features&quot; and &quot;circuits&quot; are research vocabulary; speak in behavioral contracts (schemas, acceptance) in product contexts</td></tr></tbody></table><h2 id="_3-principles" tabindex="-1">3. Principles <a class="header-anchor" href="#_3-principles" aria-label="Permalink to &quot;3. Principles&quot;">​</a></h2><p>(Deliberately minimal: derivations and experiments belong to Learn LLM Chapter 7.)</p><p>One-line chain: neurons encode multiple concepts at once (superposition) → dictionary learning / sparse autoencoders decompose activations into monosemantic &quot;features&quot; → causal tracing between features yields attribution graphs. This is a research line, not an application API — <strong>app engineers have no callable <code>explain()</code></strong>.</p><h2 id="_4-development" tabindex="-1">4. Development <a class="header-anchor" href="#_4-development" aria-label="Permalink to &quot;4. Development&quot;">​</a></h2><p><strong>Symptom → where to go</strong>:</p><ul><li>&quot;Output is unstable&quot; → not this section; go to <a href="./../03-context/">03-context</a> (contracts that narrow the degrees of freedom).</li><li>&quot;Why was this answer wrong&quot; → first <a href="./../08-production/observability.html">Observability</a> (trace reconstructs the context) and <a href="./../08-production/evaluation.html">Evaluation</a> (behavioral boundaries); most &quot;why&quot; turns out to be a context problem.</li><li>&quot;We must prove model safety to a regulator&quot; → the evidence chain in <a href="./../08-production/">08-production</a>; interpretability as research background, not as a promise.</li><li>Genuinely want to read the internals → Learn LLM Chapter 7 (Transformer internals).</li></ul><h2 id="_5-resource-library" tabindex="-1">5. Resource Library <a class="header-anchor" href="#_5-resource-library" aria-label="Permalink to &quot;5. Resource Library&quot;">​</a></h2><h3 id="pages-in-this-section" tabindex="-1">Pages in this section <a class="header-anchor" href="#pages-in-this-section" aria-label="Permalink to &quot;Pages in this section&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Page</th><th>Topic</th></tr></thead><tbody><tr><td><a href="./reasoning-ttc.html">Reasoning Models &amp; TTC</a></td><td>budgets, latency, and stop conditions for thinking-style output</td></tr><tr><td><a href="./moe-frontier.html">MoE &amp; Frontier Architectures</a></td><td>the architectural explanations behind price/speed/context caps</td></tr><tr><td><a href="./multimodal.html">Multimodal</a></td><td>minimal usage and boundaries of vision and other cross-modal abilities</td></tr></tbody></table><p>Primary sources (as published by the researchers; no content re-narrated):</p><table tabindex="0"><thead><tr><th>Name</th><th>Origin</th><th>Identifier</th></tr></thead><tbody><tr><td>Toy Models of Superposition</td><td>Anthropic (Transformer Circuits)</td><td>arXiv:2209.10652</td></tr><tr><td>Sparse Autoencoders Find Highly Interpretable Model Directions</td><td>Cunningham et al.</td><td>arXiv:2309.08600</td></tr><tr><td>Towards Monosemanticity</td><td>Anthropic (Transformer Circuits)</td><td><a href="https://transformer-circuits.pub/2023/monosemantic-features/index.html" target="_blank" rel="noreferrer">https://transformer-circuits.pub/2023/monosemantic-features/index.html</a></td></tr><tr><td>On the Biology of a Large Language Model (attribution graphs)</td><td>Anthropic (Transformer Circuits, 2025-03)</td><td><a href="https://transformer-circuits.pub/2025/attribution-graphs/biology.html" target="_blank" rel="noreferrer">https://transformer-circuits.pub/2025/attribution-graphs/biology.html</a></td></tr></tbody></table><p>(retrievedAt 2026-09-01; follow Transformer Circuits and lab publications for progress — this repo maintains no snapshots.)</p><h3 id="where-learn-ai-stops-where-to-go-next" tabindex="-1">Where learn-ai stops / where to go next <a class="header-anchor" href="#where-learn-ai-stops-where-to-go-next" aria-label="Permalink to &quot;Where learn-ai stops / where to go next&quot;">​</a></h3><ul><li>Feature decomposition, attribution-graph methods and experiments: <a href="https://llm.zenheart.site/" target="_blank" rel="noreferrer">Learn LLM</a> Chapter 7 (Transformer internals).</li><li>The &quot;why&quot; tools that actually land for applications: traces and evals (<a href="./../08-production/">08-production</a>).</li></ul>',24)])])}const y=e(o,[["render",n]]);export{m as __pageData,y as default};
